'use client';
import { useActionState } from 'react';
import { useFormStatus } from 'react-dom';

function SubmitButton() {
  const { pending } = useFormStatus();
  return <button disabled={pending}>{pending ? 'Saving...' : 'Submit'}</button>;
}

export function ProfileForm() {
  const [state, formAction, isPending] = useActionState(
    async (prev: any, formData: FormData) => {
      const res = await saveProfile(formData.get('username'));
      return res;
    },
    { error: null }
  );

  return (
    <form action={formAction}>
      <input name="username" required />
      <SubmitButton />
      {state.error && <p className="error">{state.error}</p>}
    </form>
  );
}

'use client';
import { useOptimistic, startTransition } from 'react';

export function LikeBtn({ likes }: { likes: number }) {
  const [optLikes, setOptLikes] = useOptimistic(likes, (current, inc: number) => current + inc);

  const handleLike = () => {
    startTransition(async () => {
      setOptLikes(1);
      await updateLikesServerAction();
    });
  };

  return <button onClick={handleLike}>❤️ {optLikes}</button>;
}

'use client';
import { use } from 'react';
import { ThemeContext } from './theme-context';

export function Card({ hasCustomTheme }: { hasCustomTheme: boolean }) {
  if (!hasCustomTheme) return <div>Default Card</div>;

  // ✅ Hợp lệ trong React 19!
  const theme = use(ThemeContext);
  return <div className={theme.dark}>Custom Card</div>;
}
